class Controller:
    def __init__(self, bus):
        self.bus = bus
        self.events = []
        self.callback = self.on_event
        bus.on(self.callback)
    def close(self):
        self.bus.off(lambda event: self.on_event(event))
    def on_event(self, event):
        self.events.append(event)

