class Bus:
    def __init__(self): self.callbacks = []
    def on(self, callback): self.callbacks.append(callback)
    def off(self, callback):
        self.callbacks = [registered for registered in self.callbacks if registered is not callback]
    def emit(self, event):
        for callback in list(self.callbacks): callback(event)

